WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (93::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-20T00:00:00+00:00'::TIMESTAMPTZ, '3e7551fb3063669f143d097918b9f6d96486edfd9bd6f7423cb90343a57411fd'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Las clases son muy directas, solo ir a realizar prácticas. Los videos no explican nada útil. Se pasa fácil si estudia los métodos por su cuenta. Evaluaciones en clase muy sencillas, no se pone en varas. Para las extra clase es ultra picky por varas muy random.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'bf9366e8524d70c1d2b0770865b8bb01190dd8d2b5c7341175170a02fca1640e'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'El curso es dificil sin importar el profe. Ivan explica por medio de ejemplos, deja ejercicios morales/recomendados que mete en el examen. Le encanta que le demuestren todo, entonces hay que poner cada paso que se haga por más obvio que sea. Evalua lo que enseña, entonces sirve estudiar el cuaderno.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'bb0257d0d1b640c5fc4923c28117291e30516f0327f72ed35ed7e87045b9204d'::TEXT, ARRAY[3057]::BIGINT[]),
    (93::BIGINT, 'Da notas hasta el final del semestre, los videos que da como clase teórica son suficientes para las evaluaciones pero poco profundos. Evalúa duro y para el examen da igual cuanto estudie, mete ejercicios tramposos y con cosas nunca vistas. Hay que rogarle por ayuda y cuando contesta es altanero.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '0b79a62d67456cb8ba0d74f8143706faa3877c4a9d225e90eebd37fc865cb590'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Gracias Ivan por: - - Y también por: -'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-20T00:00:00+00:00'::TIMESTAMPTZ, '495b91e2c0812a778312be17054f3316c82c5b16f43fb3398c4ee41aa8f57118'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Para este verano y habiendo llevado otro curso antes con él la verdad esta vez no tengo quejas. Explicó pacientemente y quedaba claro lo que hacía. Y responde rápido los correos. Habrá que ver si se mantiene para Neumática.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, '50476dc786e07760865db12120fca6d54354193a7ec03d706d94399f7a0d4cea'::TEXT, ARRAY[3062]::BIGINT[]),
    (93::BIGINT, 'Profesor vago y malo, muy orgulloso. Sus instrucciones son poco claras y califica duro. Califica todas las notas al final del semestre por lo que no sabe como va. El examen es difícil, no importa que haga todos los ejercicios recomendados, saca ejercicios tramposos que nunca se vieron en clase.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '52d3ae008ac89da24cd3ed312bd87ab01078012cc7daa75e2a53051d751a9180'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Entrega notas hasta el final, cero retroalimentacion y califica duro, intente seguir mucho la rubrica o conseguir trabajos de semestres pasados. Mucho es en grupo, en el curso se aprende, pero Ivan no lo hace muy ameno, en algunos casos toca aprender solo, no sabe de PLCs.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'de98b8471c5c35819a579d08737a3c59b2d6c098491d62f8fbdbb0962c2a860d'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'El experto es el experto. En cuanto a materia hace un speedrun de la materia pero los ejercicios en clase no se comparan en nada a los que salen en el exámen además de que él da ejercicios recomendados con la respuesta pero sin el procedimiento. Para los de meca no hay de otra que aguantarselo'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '1c848051fff41576b92925d37803255147e9721a9db23e8c6714c73075898605'::TEXT, ARRAY[3061]::BIGINT[]),
    (93::BIGINT, 'Clases super aburridas, poco interactivas, las da para salir del paso. Lo anterior en teoría, en laboratorio es fácil si uno hace todo a consciencia.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2022-12-01T00:00:00+00:00'::TIMESTAMPTZ, '6bf43921ebab05a729a88d1db96ed711d7b325fb891751704cb91ac632546702'::TEXT, ARRAY[3062, 3063]::BIGINT[]),
    (93::BIGINT, 'De los peores profes con los que me he topado en la carrera. Es pedante, se enreda solo al realizar sus propios ejercicios en clase, y su docencia mediocre desmotiva mucho a los estudiantes. La materia es chiva, pero el profe se encarga de lograr transmitir lo contrario.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '0958e423dfb7f3923c46cc8aab3713b3e460eac88de860a8a2bb75739f89b7aa'::TEXT, ARRAY[3062, 3063]::BIGINT[]),
    (93::BIGINT, 'Fácilmente uno de los peores profesores que he tenido en el TEC. No le importa la clase, hay que rogarle por ayuda y la mayoría de veces contesta todo altanero. Es un vago y hace el mínimo esfuerzo. Si solo puede matricular con este mae, mejor no matriculen.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-11-14T00:00:00+00:00'::TIMESTAMPTZ, '1e98e8c0e79e1cbdec31965432b941280321743b9d6e80c26eb35a5c69531188'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Si puede busque meter con otro profe, 0 recomendado, mas si no le gusta programar, el mae espera que uno sepa lenguaje de MATLAB cuando uno viene de usar python, no explica los codigos que hace en clase se los saca de la manga, lleva ejercicios que ni el sabe como resolver pero espera que uno si'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-09-03T00:00:00+00:00'::TIMESTAMPTZ, '13e6d956a3fd4e0ff26cebc9f3244bb44dbb9ab83028a75fd858896ba7941ddb'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Ningún otro profe puede dar la misma experiencia que da el Experto en cada uno de sus cursos. Neumática fue fácil, pero no por el profe. Al final hubo solo un par de clases presenciales en donde sí hubo una mejoría en los métodos del Experto, pero en lo demás es como dicen el resto de comentarios.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2022-06-06T00:00:00+00:00'::TIMESTAMPTZ, '8011e0ca97b3a87bca5dfd7ec9673c26ecbc2c38a198b6afbc0f88db2bb76ecf'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'El peor profesor de mecatrónica. Hasta vergüenza debería darle estar ahí. No sé cómo duerme sabiendo que es tan tan tan asquerosamente malo. Vago, no es atento, no escucha opiniones de estudiantes, no incita la participación, hace el mínimo esfuerzo. Si pudiera quitar a un profe del tec sería estehp'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-04-27T00:00:00+00:00'::TIMESTAMPTZ, '787646034a5c7b47022b17272cb337925984cba61411fff6f3088896c2e9630e'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f994bd82a6a906cf78112954d94773fb414254268ae845bad096ec0e05e13b7e'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Las clases son muy lentas, y el profe nunca da las soluciones completas a los ejercicios que pone de práctica. Sin embargo, si usted se mantiene al día con la materia y repasa, el curso casi que se pasa solo. Para más información vea las demás reseñas. #ExpertoSoloUno'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'b74abbc6d20be1f75561c08e134199e0a48642be8c1abdc59472dcd47836d159'::TEXT, ARRAY[3062]::BIGINT[]),
    (93::BIGINT, 'La leyenda es cierta. Un experto en aburrir, hacer la clase pesada y dejar confusa la materia. Es increíble verlo enredarse con los propios ejercicios que él mismo lleva a la clase. Califica un poco duro para lo mal que explica.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-07-31T00:00:00+00:00'::TIMESTAMPTZ, '3baaa62adc27a64dccba09269996322de57a84535bf753ff3f945e4443dbf65f'::TEXT, ARRAY[3062, 3067]::BIGINT[]),
    (93::BIGINT, 'Lo que dijo el compa de abajo. A veces me siento inútil, pero luego veo al Dios Iván y se me pasa jaja xd.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '36451cb3a395ab91c14c6db11bf7d9e4de595fb5a26ed8dd02ec0a7a0993294c'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'El Dios Iván. Este es el claro ejemplo de que cualquiera puede ser profesor jaja. Una joyita, sin lugar a dudas. Cualquier curso con él se resumen en verlo dudar durante media hora mientras hace el ejercicio que él mismo propone.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-10T00:00:00+00:00'::TIMESTAMPTZ, '3a17fda014956db0e9207cdd09bf31ec5ce80ea6dc4be834b8fcded66d287c74'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Pésimo profe, disque termo es su especialidad y ni tiene interés en el curso. Clases muy largas y solo explica cómo 3 ejercicios pues los hace en Word por lo que es súper lento, ni siquiera prepara la materia antes, y solo manda a leer capítulos del libro.Evaluaciones relativamente fáciles. ¡Huyale!'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Pocos exámenes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '90c04c72f1a9b0b39c8cffc78fb71f44f8067e7cd47c01885127f6de407d080d'::TEXT, ARRAY[3062]::BIGINT[]),
    (93::BIGINT, 'Diay, da clases en Word... da poca teoría. Resuelve ejercicios ahí, entonces se pierde MUCHO tiempo. Es MUY vago, realmente a él no le molesta regalar evaluaciones. Él sabe mucho, pero no logra enseñar correctamente. Esperemos que pronto abandone word y se compre una tablet, por lo menos xd'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'f3103f25e9abeec36104e04937d93f02edcbf5f96c169f571ba4cfa382028f1e'::TEXT, ARRAY[3062]::BIGINT[]),
    (93::BIGINT, 'Clases en Word...'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'e2caa56b30c52d3fbff67b060dcdd8fefb72648b31f319a68c605d4e7b5f5b36'::TEXT, ARRAY[3057]::BIGINT[]),
    (93::BIGINT, 'Malito, sabe mucho de la materia pero no logra transmitir el conocimiento efectivamente. Es VAGO a más no poder, no se nota el esfuerzo ni las ganas por enseñar. No hay de otra, solo él da el curso. Prepárense para las súper clases en WORD (sí, en el editor de texto word... potente el cringe)'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'b2977899b96cb09950c159fc2dd55f1b157327a345233fc118edc82271343859'::TEXT, ARRAY[3062]::BIGINT[]),
    (93::BIGINT, 'El profe tiene buen corazón, pero hay que ser claro con él y uno debe de preguntar TODO, en el primer examen no aclaró los procedimientos que queria en el examén y aun asi quito puntos. Si usted es insistente le puede llegar a explicar lo que quiere, pero necesita mas capacitaciones de docencia'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'e01d5f123f3fc39454d1cc8e9bc8c87cb9bd97f4116a20e81e5854027a931056'::TEXT, ARRAY[3057]::BIGINT[]),
    (93::BIGINT, 'El mae es super vago y si le preguntan algo es como luego o contesta como con un tonito (todos saben de que hablo), y el mae por grabar las clases no deja preguntar nada hasta que termine todo, se enreda un 50 % 50% en los ejemplos'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, '2bf73c545bfc195f374a179721ee9fbecd8afb54508aae60d90b2fb265f7b297'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Para clases virtuales hace videos de cada tema. Dejó muchas tareas en Fluidsim que eran fáciles. El proyecto lo revisa medio raro. Al examen hay que tenerle cuidado nada más pero no es nada del otro mundo. Al final cambió unos porcentajes y dejó unas tareas que revisó duro, pero el curso se pasa.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'de161df3f5fc81bf5ca2a1bba223210b029b5e7a78f93e5e223b7078485cb71b'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, '(Curso virtual) Explica relativamente bien, pero las evaluaciones son confusas y cuesta que atienda dudas. Sin importar la modalidad virtual, sí se aprendió'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '405e1fa6d5ea7f6c85236ec40da106273ab995ee822fe5a95611d4d89bc2809d'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Pues la verdad el profe hace su mejor esfuerzo por dejar la materia clara. Sin embargo, a veces cuesta entenderle. Esto se puede compensar repasando la materia y ya después entiendes muchas cosas de las que él explica.También trata de aclarar las dudas, pero en ciertas ocasiones lo hace de mala gana'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'aae639658482490c5caece73cf7697a5a25e16f0babde8a2acfbc6c57cf14218'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'pone cosas en los examenes que no se vieron en clases, cosas más dificiles y preguntas medio trampas, si no hubiera sido virtual creo que ni pasaba, habla como con pereza'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '1ccb5164626909cad9afe3a509d6876bf67c309a01fd2b2746c0316023983419'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Es vago en todo el sentido de la palabra, de los peores profesores que he tenido si no el peor. Tuve muchos comentarios que no creía pero más bien al conocerle se le quedaron cortos. Pretende que uno sepa cosas que para él son lógicas y los enunciados no son para nada claros. NO ES PROFESOR!'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '63aeb16f924c218f8c843a6ff3c4369bdffd634aa0803918f395ad07a31d0894'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Es vago y muy mal intencionado en los exámenes, no explica nada en clase ni la teoría ni los ejercicios solo escribe y escribe, no lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '123f1a8d95a19fe407dd5ec4863ec3a0cdc83f403a4628ed7f90173bf614f925'::TEXT, ARRAY[3061]::BIGINT[]),
    (93::BIGINT, 'Sin pena ni gloria'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'a6b8d62d9cd3229dd182bca3fab51481e85cdc6bd0325dd01f41812cad224087'::TEXT, ARRAY[3063]::BIGINT[]),
    (93::BIGINT, 'Es serio y un poco aburrido en clases, a veces se enreda solo y sus evaluaciones tienen enunciados confusos. Es buena gente y ayuda si ve que uno le puso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'c49b1a57a5f29738cb3dc4b3857ff6f8147a2a67233f36de200b6a9592ac1771'::TEXT, ARRAY[3061]::BIGINT[]),
    (93::BIGINT, 'Probablemente el peor del tec. No explica. Se le olvida dar datos necesarios. Pretende que en los informes uno adivine los ajustes que hay que hacerle a las fórmulas. Es aburrido y siempre dice que el laboratorio va a ser rápido y se va a salir temprano pero sale apenas con el horario o más tarde.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'fcc8e53192d5035d81d9ab7b064d5e40fa15985d58f8f2d96f275eaa49c7850d'::TEXT, ARRAY[3063]::BIGINT[]),
    (93::BIGINT, 'Simplemente el peor profesor que he tenido'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-21T00:00:00+00:00'::TIMESTAMPTZ, '94558ad09d869e0015469f57184ef451e7a8802f0f8fb81ef956f42e48fbc418'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Posiblemente sea un muy buen ingeniero, pero como profesor es una basura. Enserio no le importa que la gente aprenda. Deja trabajos con fórmulas que no se encuentran ni en internet ni en libros y muchas veces se le olvida dar datos importantes para los reportes y para resolver problemas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-10-17T00:00:00+00:00'::TIMESTAMPTZ, '896472bff5ccf9753d9ec1477f421f477f0fa6c6fe404b5f29b633bf8947b2d8'::TEXT, ARRAY[3061, 3063]::BIGINT[]),
    (93::BIGINT, 'El curso en si no es complicado, solo hay tres semanas que si se ponen pesadas, pero tienes que se autodidacta.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-12T00:00:00+00:00'::TIMESTAMPTZ, '6fa7b7085d62cc117edf402f5d5f476fd4b7fb5fa4976db5635465dcc7a3d0cd'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Es un genio incomprendido!!! y su clase es muy excitante..'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '1067081857d80c8d27acfbe17c26ed01e8726cebd077fd5ab17788a09f950c55'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'No se le acerque a esta cosa'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, '264be37e2bae267b268eab8ad54c8311ccd683cc18ee673f82b209223c8f83ed'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Pesimo explicando se le olvidaba darnos datos necesarios para realizar los informes.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'ae7c02004db9cb21a4409ff2488f5971561a6a87b52a48b095b8231df7141c93'::TEXT, ARRAY[3063]::BIGINT[]),
    (93::BIGINT, 'Malo y con ganas la verdad sin palabras...'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '256850354851a689e0cf64f1cb7319e0d881f03e0448705d431df393e4fe0300'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Su dominio de la materia es deplorable'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd019e5aba06275a9f6bd99e262810d172655d6d15213572d1b41facde7c8ac47'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4e57d4b2ce249c58817893164d922e8e71a6ec5c13e5eaa0b78fbef438484c71'::TEXT, ARRAY[3063]::BIGINT[]),
    (93::BIGINT, 'Las prácticas de Matlab son muy difíciles y no están acorde a lo que enseña'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'c5e488f57abfc4aa88d35c2c38dbae87537982b2caf18b6f78ce8ae05e8ab7f9'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, '¿Cuenta como profesor?'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '32c72bb9749f4e29192c97aaa80c59f031fa737c4a481ca1ca1a8c092a484e6e'::TEXT, ARRAY[3053]::BIGINT[]),
    (93::BIGINT, 'El peor profesor del ITCR'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '485d8173fe82930ebbe6f3b6384a0fd6e58120b4c179b5bcea0a709c4e72a3d9'::TEXT, ARRAY[3053]::BIGINT[]),
    (93::BIGINT, 'Falta de dominio de la materia, me parece sería importante llegar al laboratorio con el dominio adecuado, pero como la materia no va del todo de la mano con el conocimiento necesario para este, se pierde mucho tiempo intentado entender lo que él debió explicar en teoría.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'd293780858042c991975d917c1ae306373fcac3536b3072cfbcbbda4b58af912'::TEXT, ARRAY[3053]::BIGINT[]),
    (93::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-31T00:00:00+00:00'::TIMESTAMPTZ, 'a09fd6bdf0ff9fa4b1ddebe43276fac95ed0ba27c4af5012c6f5beb6a46c30d6'::TEXT, ARRAY[3067]::BIGINT[]),
    (93::BIGINT, 'Pésimo profesor. No sabe explicar, no domina la materia, es mediocre, no se apasiona por lo que hace.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'd38cc4abd9e1ac26d5a7a9f6c56081f857fd5442a2150fdf67b943a081802f07'::TEXT, ARRAY[3057, 3063]::BIGINT[]),
    (93::BIGINT, 'Pésimo, sólo llega a leer diapositivas y esa es la clase, no domina la materia...'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'e3ed995abdae6bcf214a00e9ee7478ca7249d703f27f2ae9f1d3a3eed8d40461'::TEXT, ARRAY[3053]::BIGINT[]),
    (93::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '1beb49cc704c4bcb4a46fad0d5acd0340639b303ee3c4315b9b293539e48c59b'::TEXT, ARRAY[3057]::BIGINT[]),
    (93::BIGINT, 'Es un profesor malisimo, para explicar y para evaluar. A veces se levanta con ganas de intentar ser tuanis, pero se le pasa rapido.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9316740955343472ae9d4e66ce86998309a75ffee1a935e5a48be6cf462845a0'::TEXT, ARRAY[3053]::BIGINT[]),
    (93::BIGINT, 'Pesimo Profesor...'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7af33261d2ebb5b99dff029a5c160ac20499aab111ff43d3ebeccf5d4cb12d2e'::TEXT, ARRAY[3053]::BIGINT[]),
    (93::BIGINT, 'No sabe ni donde esta parado. El curso se pasa porque el profe ayuda pero no se aprende nada'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'c71f8a5a8f3e4f3fc8abaae1d647afd5806d48e4224d1c236fd27b5e1c80be0b'::TEXT, ARRAY[3057]::BIGINT[]),
    (93::BIGINT, 'No explica muy bien, parece no dominar bien la materia en el momento en que uno le realiza consultas y preguntas solo dice: eso es conceptual'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-16T00:00:00+00:00'::TIMESTAMPTZ, '3f0343d56026bd13b679d751e93a3063f33b2826f12d87e1afe3c225cb786408'::TEXT, ARRAY[3062]::BIGINT[]),
    (93::BIGINT, 'Simplemente no sabe hacer examenes, las instrucciones para el examen sólo el las entiende la verdad'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '5c57d8fb6ea9a0ff46253d12eaee0ea9482e02e5ece86c03f4ba264d9f1f189c'::TEXT, ARRAY[3053]::BIGINT[]),
    (93::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'c7157f99a75027679acb433615d5e66ebcacc1c609009b02d8fcce2da34b6ec6'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Su conocimiento se encuentra escrito en una libreta, si no está en ella no sabe; incluso en ella tiene errores que llevan años. Le gusta sacar evaluaciones extra difíciles para no sentirse solo en la consulta.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '76f9e9ebf254aa0ce342f04af34e5eb2c10acd0f26e6ba168bd2b8aab4e3b3ca'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'No sabe explicar bien ni contestar las dudas claramente, entrega los resultados de los trabajos cuando le da la gana'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'e9014cd4b79077193a2d3c76d933fead260c3f9a99f7eb6d0cfe42cb50c99688'::TEXT, ARRAY[968]::BIGINT[]),
    (93::BIGINT, 'Buen profe, le falta explicar un poco más pero ayuda a que la mayoria de los estudiantes pasen el curso'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'fde9f058cfdff570c599e2c4983ad4c8445beae82018694366966ce1afac4ace'::TEXT, ARRAY[3057]::BIGINT[]),
    (93::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '5ab7bed899a2b7db855b36ed84bb09802d0a3a4ab1d73110b6643aad3bf55e85'::TEXT, ARRAY[3053]::BIGINT[]),
    (93::BIGINT, 'Unico prome, es malo los examenes duros y no explica nada bien'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a0853d0bd5f4f0cfa9ebd2f6f1d849d152fe15e11ce29c95cae190f33f31a8c6'::TEXT, ARRAY[3057]::BIGINT[]),
    (93::BIGINT, 'En 4 años en el tec ha sido el peor!!!! Pésimo profe y hace exámenes demasiado duros con cosas nunca antes vistas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'a358b910b3a3a51388353937fa25ebd9bb030f4a272f1ceccf549b4bfeaf031b'::TEXT, ARRAY[3053]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
